#!/usr/bin/env bashset -euo pipefail# Generar BOM (dev): (ejecutar localmente cuando actualizas deps)# pip freeze > .bom/requirements.txt# Verificar en CI que no hay cambios inesperados (falla si cambia .bom/requirements.txt)# pip install -r requirements-dev.txt# pip freeze > .bom/requirements_ci.txt# git --no-pager diff --exit-code .bom/requirements_ci.txt .bom/requirements.txt || (echo "BOM out of date" && exit 1)# Escaneo de vulnerabilidades# pip install pip-audit# pip-audit --json -o .bom/pip-audit.json